// Wir erstellen eine neue, leere Liste für unsere bereinigten Ergebnisse.
const newItems = [];

// Wir gehen durch jedes komplexe Objekt (Item) in der eingehenden Liste.
for (const item of items) {
  let inputText = null;

  // --- Sicherer Zugriff im "klassischen" Stil ---
  // Wir prüfen Schritt für Schritt, ob jeder Teil des Pfades existiert.
  if (item.json &&
      item.json.choices &&
      Array.isArray(item.json.choices) &&
      item.json.choices.length > 0 &&
      item.json.choices[0].message &&
      typeof item.json.choices[0].message.content === 'string') {
    // Nur wenn der gesamte Pfad gültig ist, weisen wir den Text zu.
    inputText = item.json.choices[0].message.content;
  }

  // Wir fahren nur fort, wenn wir den Text erfolgreich extrahieren konnten.
  if (inputText) {
    let processedText = inputText;

    // Schritt 1: Entferne den Markdown-Codeblock-Wrapper.
    processedText = processedText.replace('```markdown\n', '');
    processedText = processedText.replace(/```$/, '');

    // Schritt 2: Bereinige den Text von Leerraum am Anfang und Ende.
    const cleanedText = processedText.trim();

    // Schritt 3: Erstelle ein neues, sauberes Objekt und füge es zur Ergebnisliste hinzu.
    newItems.push({
      json: {
        text: cleanedText
      }
    });
  }
}

// Gib die neue Liste mit den bereinigten Texten als Ergebnis zurück.
return newItems;

const item = items[0];
const daten = JSON.parse(JSON.stringify(item.json));
const themaObject = daten.Uebergabedaten?.[0]?.Kunden?.[0]?.Servicegruppen?.[0]?.Services?.[0];

let sonstigeDaten = [];

if (themaObject && themaObject.Sonstige) {
  // Die Sonstige-Daten in eine separate Variable kopieren
  sonstigeDaten = themaObject.Sonstige;
  // Den "Sonstige"-Block aus dem Haupt-Objekt löschen
  delete themaObject.Sonstige;
}

// Ein einziges Item zurückgeben, das beide Teile enthält
return [{
  json: {
    hauptdaten: daten,
    sonstige: sonstigeDaten
  }
}];

// Wir erstellen eine neue, leere Liste für unsere bereinigten Ergebnisse.
const newItems = [];

// Wir gehen durch jedes komplexe Objekt (Item) in der eingehenden Liste.
for (const item of items) {
  // Zugriff auf die Hauptdaten des aktuellen Items
  const inputData = item.json;

  let inputText = null;

  // --- Sicherer Zugriff ---
  // Da die AI-Antwort nun im Unterobjekt "AI_Response" liegt,
  // müssen wir den Pfad entsprechend anpassen: inputData.AI_Response...
  if (inputData &&
      inputData.AI_Response &&
      inputData.AI_Response.choices &&
      Array.isArray(inputData.AI_Response.choices) &&
      inputData.AI_Response.choices.length > 0 &&
      inputData.AI_Response.choices[0].message &&
      typeof inputData.AI_Response.choices[0].message.content === 'string') {

    // Text aus dem verschachtelten Objekt holen
    inputText = inputData.AI_Response.choices[0].message.content;
  }

  // Wir fahren nur fort, wenn wir den Text erfolgreich extrahieren konnten.
  if (inputText) {
    let processedText = inputText;

    // Schritt 1: Entferne den Markdown-Codeblock-Wrapper.
    // (Nutzt Regex /^.../ um sicherzustellen, dass es am Anfang steht, ist aber optional)
    processedText = processedText.replace('```markdown\n', '');
    processedText = processedText.replace(/```$/, '');

    // Schritt 2: Bereinige den Text von Leerraum am Anfang und Ende.
    const cleanedText = processedText.trim();

    // Schritt 3: Erstelle ein neues, sauberes Objekt.
    // WICHTIG: Wir übernehmen hier auch Kunde und Servicegruppe, 
    // damit wir später noch wissen, wozu der Text gehört.
    newItems.push({
      json: {
        Kunde: inputData.Kunde,
        Servicegruppe: inputData.Servicegruppe,
        Service: inputData.Service,
        text: cleanedText
      }
    });
  }
}

// Gib die neue Liste zurück
return newItems;

// Ein Array initialisieren, um die Ergebnisse für jedes Item zu sammeln
const outputItems = [];

// Eine Schleife über ALLE eingehenden Items statt nur das erste zu nehmen
for (const item of $input.all()) {

  // Die allgemeinen Daten aus dem "hauptdaten"-Objekt abrufen
  const allgemeineDaten = item.json;

  // Die spezifischen Daten der Servicegruppe aus dem "flachen" Schlüssel abrufen
  // Dieser Schlüsselname entsteht oft, wenn n8n Daten aufteilt (split out)
  const servicegruppenDaten = '';

  // Die beiden Datenquellen zu einem vollständigen "Uebergabedaten"-Objekt zusammenbauen,
  // das der ursprünglichen Struktur entspricht, die der Prompt erwartet.
  const kompletteUebergabedaten = [
    {
