if (introEndIndex > introMarker.length - 1 && instructionStartIndex > introEndIndex) {
  const introPart = fullUserPrompt.substring(0, introEndIndex);
  const instructionPart = fullUserPrompt.substring(instructionStartIndex);

  genericUserPrompt = introPart.trim() + ' ' + instructionPart.trim();
} else {
  // Fallback, falls die Struktur des Prompts unerwartet ist.
  genericUserPrompt = "FEHLER: Der generische user_prompt konnte nicht erstellt werden, da die Marker nicht gefunden wurden.";
}

// Der bereinigte, generische user_prompt wird zum Objekt mit den gemeinsamen Daten hinzugefügt.
commonData.user_prompt = genericUserPrompt;


// --- Schritt 3: Jedes Item durchlaufen, um die nun redundanten Daten zu entfernen ---
const processedItems = items.map(item => {
  // Eine Kopie des JSON-Objekts des Items wird erstellt.
  const newItem = { ...item.json };

  // Die Schlüssel, die in das übergeordnete Objekt verschoben wurden, werden hier gelöscht.
  delete newItem.model;
  delete newItem.temperature;
  delete newItem.system_prompt;
  delete newItem.user_prompt;
  delete newItem.request_id; // Das neue Feld wird ebenfalls entfernt.

  return newItem;
});


// --- Schritt 4: Die finale Ausgabestruktur zusammensetzen ---
// Dieses Objekt enthält die gemeinsamen Daten und das Array der bereinigten Items als "Geschwister"-Elemente.
const finalOutput = {
  json: {
    ...commonData,
    items: processedItems
  }
};


// Der n8n "Code" Node erwartet als Rückgabewert ein Array von Items.
return [finalOutput];

// Zugriff auf das Ergebnis des HTTP Requests (der direkte Input in diesen Node)
const httpResult = $input.item.json;

// Zugriff auf die Daten des "Edit Fields2" Nodes für das aktuelle Item
// $('NodeName').item greift automatisch auf das passende Item im Loop zu
const contextData = $('Edit Fields2').item.json;

// Wir geben ein kombiniertes Objekt zurück
return {
  json: {
    // 1. Die ursprünglichen Daten (Kunde, Servicegruppe) behalten
    Kunde: contextData.Kunde,
    Servicegruppe: contextData.Servicegruppe,
    Service: contextData.Service,

    // 2. Die Antwort der API hinzufügen (z.B. choices oder content)
    // Hier wird die gesamte Antwort in ein Unterfeld gepackt, damit es übersichtlich bleibt
    AI_Response: httpResult,

    // Optional: Falls du nur den Text der AI willst (pass den Pfad ggf. an deine API-Antwort an):
    // AI_Text: httpResult.choices?.[0]?.message?.content || "Keine Antwort"
  }
};
